CREATE TABLE hostels (hostel TEXT PRIMARY KEY, warden TEXT NOT NULL);
CREATE TABLE students (roll TEXT PRIMARY KEY, name TEXT NOT NULL, hostel TEXT NOT NULL REFERENCES hostels(hostel));
CREATE TABLE items (item TEXT PRIMARY KEY, price INTEGER NOT NULL);
CREATE TABLE orders (order_id INTEGER PRIMARY KEY, roll TEXT NOT NULL REFERENCES students(roll));
CREATE TABLE order_lines (order_id INTEGER NOT NULL REFERENCES orders(order_id), item TEXT NOT NULL REFERENCES items(item), qty INTEGER NOT NULL, PRIMARY KEY (order_id, item));
